effect.shader:
vec4 src(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
float hash11(float n){ return fract(sin(n)*43758.5453123); }
float hash12(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)) + seed)*43758.5453); }
vec2  hash22(vec2 p){
float n = sin(dot(p, vec2(12.9898,78.233)) + seed);
return fract(vec2(262144.0, 32768.0) * n);
}
void main(){
vec2 uv = acScreenNorm;
vec2 px = uv * acScreenSize;
float D = max(density, 1e-3);
float area = acScreenSize.x * acScreenSize.y;
float cells = D * (area / 1000000.0);
float cellSize = sqrt(max(area / max(cells, 1.0), 1.0));
vec2 cell = floor(px / cellSize);
vec2 cellOrigin = cell * cellSize;
vec2 rnd = hash22(cell);
float t = acTime * speed;
vec2 drift = 0.35 * (rnd - 0.5) * cellSize * t;
vec2 center = cellOrigin + (rnd * cellSize) + drift;
float r = max(dotSize, 0.0);
float d = length(px - center);
float feather = mix(0.001, 0.8, clamp(softness, 0.0, 1.0));
float m = 1.0 - smoothstep(r, r * (1.0 + feather), d);
float f = mix(1.0, hash12(cell + floor(t*7.0)), flicker);
m *= f;
vec4 base = src(uv);
vec3 dotRGB = dotColor.rgb * opacity * m;
int bm = int(blendMode);
vec3 outRGB;
if (bm == 1) {
vec3 mixed = mix(base.rgb, dotRGB, clamp(mixAmount, 0.0, 1.0));
outRGB = mixed;
} else if (bm == 2) {
outRGB = base.rgb + dotRGB * clamp(mixAmount, 0.0, 1.0);
} else if (bm == 3) {
vec3 scr = 1.0 - (1.0 - base.rgb) * (1.0 - clamp(dotRGB, 0.0, 100.0));
outRGB = mix(base.rgb, scr, clamp(mixAmount, 0.0, 1.0));
} else {
vec3 mul = base.rgb * (1.0 - m + dotRGB);
outRGB = mix(base.rgb, mul, clamp(mixAmount, 0.0, 1.0));
}
gl_FragColor = vec4(outRGB, base.a);
}
